/// <summary>
///    AVA <c>displayAVAGetNameWithTitle</c> method.
/// </summary>
/// <returns>
///    <c>AVAContactName</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public display AVAContactName displayAVAGetNameWithTitle()
{
    AVAContactName retVal;

    retVal = this.DirPerson().avaGetNameWithTitle();

    return retVal;
}

/// <summary>
/// Display method to show the name of the contact person that confirmed or rejected the version
/// </summary>
public display DirPartyName avaPersonName()
{
    return this.DirPerson().name(DirPersonName::find(this.Person));
}
